{% set toolmap = printer["gcode_macro TOOL_MAP"].map %}
{% set slot = toolmap[logical] %}
{% set msg = "T" ~ logical ~ " -> SLOT " ~ slot %}
RESPOND PREFIX=TEST MSG="{msg}"

