BED_PIN_APPLY_OFFSET TOOL=T1

ACTIVATE_EXTRUDER EXTRUDER=extruder1

_SYNC_ACTIVE_TOOL_FAN S={printer["gcode_macro M106"].last_s}
SET_VELOCITY_LIMIT ACCEL={previous_accel}

