SET_GCODE_VARIABLE MACRO=_FILAMENT_STATE VARIABLE=new_t2 VALUE=1
{% else %}
SET_GCODE_VARIABLE MACRO=_FILAMENT_STATE VARIABLE=new_t3 VALUE=1
{% endif %}

